+    let rot = |p: Point2, ang: f64| {
+        let (sn, cs) = ang.sin_cos();
+        let (dx, dy) = (p.x - o.x, p.y - o.y);
+        Point2::new(o.x + dx * cs - dy * sn, o.y + dx * sn + dy * cs)
